CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','restricted')), display_name text NOT NULL DEFAULT '创作者', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identities(user_id uuid NOT NULL REFERENCES users, kind text NOT NULL, identifier text NOT NULL, verified_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(kind,identifier));
CREATE TABLE auth_challenges(id uuid PRIMARY KEY, purpose text NOT NULL, target text NOT NULL, code_hash text NOT NULL, ip_hash text NOT NULL, device_hash text NOT NULL, attempt_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE INDEX auth_challenge_target_time ON auth_challenges(target,created_at);
CREATE INDEX auth_challenge_ip_time ON auth_challenges(ip_hash,created_at);
CREATE TABLE devices(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, installation_id text NOT NULL, public_key text NOT NULL, label text NOT NULL, platform text NOT NULL, app_version text NOT NULL, disabled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,installation_id));
CREATE TABLE sessions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, device_id uuid NOT NULL REFERENCES devices, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refresh_tokens(digest text PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions, expires_at timestamptz NOT NULL, used_at timestamptz, retry_key text, retry_request_hash text, retry_ciphertext text, retry_until timestamptz);
CREATE TABLE device_challenges(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions, purpose text NOT NULL, nonce text NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE request_nonces(device_id text NOT NULL,nonce text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(device_id,nonce));
CREATE TABLE license_products(id text NOT NULL, version text NOT NULL, name text NOT NULL, kind text NOT NULL CHECK(kind IN('trial','subscription','perpetual')), duration_days integer CHECK(duration_days > 0), device_limit integer NOT NULL CHECK(device_limit BETWEEN 1 AND 100), features jsonb NOT NULL, enabled boolean NOT NULL DEFAULT false, PRIMARY KEY(id,version));
CREATE TABLE activation_codes(id uuid PRIMARY KEY, digest text NOT NULL UNIQUE, suffix text NOT NULL, product_id text NOT NULL, product_version text NOT NULL, expires_at timestamptz, revoked_at timestamptz, redeemed_by uuid REFERENCES users, redeemed_at timestamptz, FOREIGN KEY(product_id,product_version) REFERENCES license_products);
CREATE TABLE entitlements(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, product_id text NOT NULL, product_version text NOT NULL, kind text NOT NULL, features jsonb NOT NULL, device_limit integer NOT NULL CHECK(device_limit > 0), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')), expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE redemptions(code_id uuid PRIMARY KEY REFERENCES activation_codes, user_id uuid NOT NULL REFERENCES users, entitlement_id uuid NOT NULL REFERENCES entitlements, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE device_bindings(device_id uuid NOT NULL REFERENCES devices, entitlement_id uuid NOT NULL REFERENCES entitlements, bound_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, PRIMARY KEY(device_id,entitlement_id));
CREATE TABLE wallets(user_id uuid PRIMARY KEY REFERENCES users, available_units bigint NOT NULL DEFAULT 0 CHECK(available_units >= 0), reserved_units bigint NOT NULL DEFAULT 0 CHECK(reserved_units >= 0), frozen_units bigint NOT NULL DEFAULT 0 CHECK(frozen_units >= 0), revision bigint NOT NULL DEFAULT 0);
CREATE TABLE ledger_transactions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, business_key text NOT NULL UNIQUE, kind text NOT NULL, reference_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_postings(id bigserial PRIMARY KEY, transaction_id uuid NOT NULL REFERENCES ledger_transactions, account text NOT NULL, units bigint NOT NULL CHECK(units <> 0));
CREATE INDEX ledger_user_history ON ledger_transactions(user_id,created_at DESC);
CREATE FUNCTION deny_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable ledger'; END $$;
CREATE TRIGGER immutable_transactions BEFORE UPDATE OR DELETE ON ledger_transactions FOR EACH ROW EXECUTE FUNCTION deny_ledger_mutation();
CREATE TRIGGER immutable_postings BEFORE UPDATE OR DELETE ON ledger_postings FOR EACH ROW EXECUTE FUNCTION deny_ledger_mutation();
CREATE FUNCTION check_balanced_ledger() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (SELECT COALESCE(sum(units),0) FROM ledger_postings WHERE transaction_id=NEW.transaction_id) <> 0 THEN RAISE EXCEPTION 'unbalanced ledger'; END IF;
  RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER balanced_ledger AFTER INSERT ON ledger_postings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_balanced_ledger();
CREATE FUNCTION post_ledger(p_id uuid,p_user uuid,p_key text,p_kind text,p_ref text,p_available bigint,p_reserved bigint,p_frozen bigint,p_system bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
  IF p_available+p_reserved+p_frozen+p_system <> 0 THEN RAISE EXCEPTION 'unbalanced ledger'; END IF;
  PERFORM 1 FROM wallets WHERE user_id=p_user FOR UPDATE;
  INSERT INTO ledger_transactions(id,user_id,business_key,kind,reference_id) VALUES(p_id,p_user,p_key,p_kind,p_ref);
  INSERT INTO ledger_postings(transaction_id,account,units)
    SELECT p_id,account,units FROM (VALUES('user:'||p_user||':available',p_available),('user:'||p_user||':reserved',p_reserved),('user:'||p_user||':frozen',p_frozen),('platform:'||CASE WHEN p_kind IN('recharge','grant','refund') THEN 'issued' ELSE 'consumed' END,p_system)) AS p(account,units) WHERE units <> 0;
  UPDATE wallets SET available_units=available_units+p_available,reserved_units=reserved_units+p_reserved,frozen_units=frozen_units+p_frozen,revision=revision+1 WHERE user_id=p_user;
  IF NOT FOUND THEN RAISE EXCEPTION 'wallet missing'; END IF;
  RETURN p_id;
END $$;
REVOKE ALL ON FUNCTION post_ledger(uuid,uuid,text,text,text,bigint,bigint,bigint,bigint) FROM PUBLIC;
CREATE TABLE credit_lots(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, source_id text NOT NULL, source_kind text NOT NULL CHECK(source_kind IN('paid','bonus','grant')), original_units bigint NOT NULL CHECK(original_units>0), available_units bigint NOT NULL CHECK(available_units>=0), reserved_units bigint NOT NULL DEFAULT 0 CHECK(reserved_units>=0), frozen_units bigint NOT NULL DEFAULT 0 CHECK(frozen_units>=0), consumed_units bigint NOT NULL DEFAULT 0 CHECK(consumed_units>=0), revoked_units bigint NOT NULL DEFAULT 0 CHECK(revoked_units>=0), created_at timestamptz NOT NULL DEFAULT now(), CHECK(original_units=available_units+reserved_units+frozen_units+consumed_units+revoked_units));
CREATE TABLE recharge_products(id text NOT NULL, version text NOT NULL, name text NOT NULL, amount_fen bigint NOT NULL CHECK(amount_fen>0), paid_units bigint NOT NULL CHECK(paid_units>0), bonus_units bigint NOT NULL DEFAULT 0 CHECK(bonus_units>=0), enabled boolean NOT NULL DEFAULT false, PRIMARY KEY(id,version));
CREATE TABLE recharge_orders(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, product_id text NOT NULL, product_version text NOT NULL, provider text NOT NULL, amount_fen bigint NOT NULL CHECK(amount_fen>0), paid_units bigint NOT NULL, bonus_units bigint NOT NULL, currency text NOT NULL DEFAULT 'CNY', status text NOT NULL DEFAULT 'created', provider_trade_id text, payment_action jsonb, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), credited_at timestamptz, UNIQUE(provider,provider_trade_id));
CREATE TABLE payment_events(provider text NOT NULL,event_id text NOT NULL,order_id uuid NOT NULL REFERENCES recharge_orders,digest text NOT NULL,verified_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider,event_id));
CREATE TABLE refunds(id uuid PRIMARY KEY, order_id uuid NOT NULL UNIQUE REFERENCES recharge_orders, user_id uuid NOT NULL REFERENCES users, amount_fen bigint NOT NULL, units bigint NOT NULL, status text NOT NULL, reason text NOT NULL, provider_refund_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE model_entries(id text NOT NULL, version text NOT NULL, capability text NOT NULL CHECK(capability IN('text','image','video','music','tts','speechToText','vision')), operation text NOT NULL, display_name text NOT NULL, route_id uuid NOT NULL, parameter_schema jsonb NOT NULL, enabled boolean NOT NULL DEFAULT false, is_default boolean NOT NULL DEFAULT false, PRIMARY KEY(id,version));
CREATE TABLE provider_routes(id uuid PRIMARY KEY, adapter text NOT NULL CHECK(adapter IN('suno','openai-text','openai-image','openai-speech','openai-transcription','openai-vision','async-video','fixture')), origin text NOT NULL, credential_ref text NOT NULL, upstream_model text NOT NULL, options jsonb NOT NULL DEFAULT '{}', enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE model_entries ADD FOREIGN KEY(route_id) REFERENCES provider_routes;
CREATE TABLE rate_versions(id text PRIMARY KEY, model_id text NOT NULL, model_version text NOT NULL, unit text NOT NULL CHECK(unit IN('request','image','second','character','token')), units_per_quantity bigint NOT NULL CHECK(units_per_quantity>0), max_quantity bigint NOT NULL CHECK(max_quantity>0), minimum_success integer NOT NULL DEFAULT 1 CHECK(minimum_success>0), published_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(model_id,model_version) REFERENCES model_entries);
CREATE TRIGGER immutable_rates BEFORE UPDATE OR DELETE ON rate_versions FOR EACH ROW EXECUTE FUNCTION deny_ledger_mutation();
CREATE TABLE quotes(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, model_id text NOT NULL, model_version text NOT NULL, rate_id text NOT NULL REFERENCES rate_versions, capability text NOT NULL, operation text NOT NULL, params jsonb NOT NULL, input_hash text NOT NULL, reserved_units bigint NOT NULL CHECK(reserved_units>0), quantity bigint NOT NULL CHECK(quantity>0), route_snapshot jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE generation_jobs(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, quote_id uuid NOT NULL UNIQUE REFERENCES quotes, client_operation_id text NOT NULL, state text NOT NULL DEFAULT 'reserved', reserved_units bigint NOT NULL CHECK(reserved_units>0), settled_units bigint NOT NULL DEFAULT 0 CHECK(settled_units>=0), released_units bigint NOT NULL DEFAULT 0 CHECK(released_units>=0), upstream_id text, submission_key uuid NOT NULL UNIQUE, attempt_started_at timestamptz, lease_until timestamptz, next_poll_at timestamptz NOT NULL DEFAULT now(), lease_owner uuid, failure_code text, result jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,client_operation_id), CHECK(settled_units+released_units<=reserved_units));
CREATE TABLE lot_allocations(job_id uuid NOT NULL REFERENCES generation_jobs, lot_id uuid NOT NULL REFERENCES credit_lots, reserved_units bigint NOT NULL CHECK(reserved_units>0), consumed_units bigint NOT NULL DEFAULT 0 CHECK(consumed_units>=0), released_units bigint NOT NULL DEFAULT 0 CHECK(released_units>=0), PRIMARY KEY(job_id,lot_id), CHECK(consumed_units+released_units<=reserved_units));
CREATE TABLE artifacts(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, job_id uuid NOT NULL REFERENCES generation_jobs, object_key text NOT NULL, sha256 text NOT NULL, size bigint NOT NULL CHECK(size>0), mime text NOT NULL, label text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id,object_key));
CREATE TABLE upload_assets(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,object_key text NOT NULL,size bigint NOT NULL CHECK(size BETWEEN 1 AND 52428800),mime text NOT NULL,sha256 text NOT NULL,verified boolean NOT NULL DEFAULT false,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_requests(scope text NOT NULL,key text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope,key));
CREATE TABLE outbox_events(id uuid PRIMARY KEY,kind text NOT NULL,reference_id text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE TABLE audit_events(id uuid PRIMARY KEY,actor text NOT NULL,action text NOT NULL,reference_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE release_manifests(id uuid PRIMARY KEY,platform text NOT NULL,arch text NOT NULL,channel text NOT NULL,version text NOT NULL,build bigint NOT NULL,manifest jsonb NOT NULL,rollout integer NOT NULL DEFAULT 0 CHECK(rollout BETWEEN 0 AND 100),enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(platform,arch,channel,build));
CREATE TABLE operator_users(user_id uuid PRIMARY KEY REFERENCES users,role text NOT NULL CHECK(role IN('support','finance','admin')),enabled boolean NOT NULL DEFAULT true);
